FICHES.append(fiche(
 id='bukele-salvador-modele', affirmation="Le Salvador de Bukele a éradiqué le crime, il faut faire pareil en France.", volet='international', sous_theme='Amérique latine',
 mots_cles=['bukele', 'salvador', 'el salvador gangs', 'modele bukele', 'salvador criminalite', 'cecot', 'faire comme au salvador', 'bukele en france', 'mega prison salvador'],
 verdict='trompeur', fiabilite='etabli',
 resume="Trompeur. La baisse des homicides au Salvador est réelle et spectaculaire : de 106 pour 100 000 habitants en 2015 à 1,9 en 2024 selon les chiffres officiels, peu vérifiables. Mais elle repose sur un régime d'exception prolongé depuis 2022 : plus de 90 000 arrestations, près de 2 % de la population en prison, au moins 470 morts en détention, et selon Amnesty des faits qui pourraient constituer des crimes contre l'humanité. Avant cela, le gouvernement avait négocié en secret avec les gangs.",
 contexte="Le président salvadorien Nayib Bukele est devenu une référence pour une partie de la droite et de l'extrême droite européennes, qui citent sa « guerre contre les gangs » comme modèle.",
 explication="Il faut regarder l'évolution des homicides, mais aussi les méthodes employées, les droits fondamentaux, la fiabilité des chiffres et ce que la situation de départ du Salvador a de comparable avec la France.",
 sources=[SV_HRW_2026, SV_AMNESTY_2026, SV_CGRA_2025, SV_INSIGHT_2021, SV_ONU_2023, SV_AP_2025],
 faits=[
  fait("Selon les chiffres officiels, le taux d'homicides passe de 106 pour 100 000 habitants en 2015 à 7,8 en 2022 et 1,9 en 2024 (114 homicides en 2024).", 'sv_cgra_2025', '2015-2024', 'Salvador', "La baisse est réelle et massive ; il ne faut pas la nier.", 'estimation', '1,9'),
  fait("Le régime d'exception de mars 2022 a été prolongé 45 fois ; plus de 90 000 personnes ont été arrêtées, dont plus de 3 000 enfants, et 1,9 % de la population est détenue.", 'sv_hrw_2026', '2022-2026', 'Salvador', "C'est l'un des taux d'incarcération les plus élevés au monde, obtenu en suspendant des libertés.", 'etabli', '90 000'),
  fait("Selon Amnesty International, au moins 470 personnes sont mortes en détention, et les détentions arbitraires de masse pourraient constituer des crimes contre l'humanité.", 'sv_amnesty_2026', '2022-2026', 'Salvador', "Le prix humain est énorme, y compris pour des innocents.", 'etabli', '470'),
  fait("Entre 25 000 et 30 000 personnes présumées innocentes seraient détenues ; les données pénitentiaires sont confidentielles depuis 2021 et la méthode de comptage des homicides a changé.", 'sv_cgra_2025', '2021-2025', 'Salvador', "Les chiffres du succès sont produits par un pouvoir qui contrôle l'information.", 'estimation'),
  fait("Avant 2022, des responsables du gouvernement Bukele ont négocié en secret avec les gangs, selon le Trésor américain : baisse des homicides et soutien électoral contre des avantages en prison.", 'sv_insight_2021', '2019-2021', 'Salvador', "La baisse des homicides a commencé par un pacte avec les criminels, pas seulement par la répression.", 'etabli'),
  fait("Fait défavorable : Bukele est très populaire et a été réélu, malgré l'interdiction constitutionnelle de la réélection consécutive.", 'sv_ap_2025', '2024', 'Salvador', "Beaucoup de Salvadoriens soutiennent cette politique ; c'est aussi ce qui rend la dérive autoritaire dangereuse.", 'etabli'),
 ],
 court="Les homicides ont bien chuté au Salvador. Mais au prix d'un régime d'exception depuis 2022 : plus de 90 000 arrestations, des milliers d'innocents détenus, au moins 470 morts en prison. Et la France part d'un taux d'homicides 50 fois plus bas que le Salvador de 2015.",
 moyen="Les chiffres officiels montrent une baisse spectaculaire des homicides : 106 pour 100 000 habitants en 2015, 1,9 en 2024. C'était l'un des pays les plus violents du monde, dominé par des gangs.\n\nLa méthode, c'est un régime d'exception prolongé 45 fois depuis 2022 : plus de 90 000 personnes arrêtées, souvent sans lien avec les gangs selon Human Rights Watch, au moins 470 morts en détention selon Amnesty. Avant cela, le gouvernement avait négocié en secret avec les gangs. Copier ce modèle en France voudrait dire suspendre les droits de tous pour un problème sans commune mesure.",
 detaille="En 2015, le Salvador comptait 106 homicides pour 100 000 habitants, l'un des taux les plus élevés au monde, avec des gangs qui contrôlaient des quartiers entiers. En 2024, selon les chiffres officiels, ce taux est tombé à 1,9. Cette baisse est réelle et explique la popularité du président Bukele.\n\nMais il faut regarder comment. Depuis mars 2022, un régime d'exception suspend des libertés fondamentales ; il a été prolongé 45 fois. Plus de 90 000 personnes ont été arrêtées, dont plus de 3 000 enfants, souvent sur leur apparence, leurs tatouages ou des dénonciations anonymes. Près de 2 % de la population est en prison, et entre 25 000 et 30 000 détenus seraient innocents. Au moins 470 personnes sont mortes en détention. Amnesty International estime que ces faits pourraient constituer des crimes contre l'humanité, et des experts de l'ONU dénoncent des procès de masse. Avant la répression, le gouvernement avait négocié en secret avec les gangs, selon le Trésor américain. Et les chiffres sont produits par un pouvoir qui a rendu les données pénitentiaires confidentielles.\n\nLa France n'a rien de comparable : son taux d'homicides était environ 50 fois plus faible que celui du Salvador de 2015. Importer ce modèle reviendrait à suspendre les droits de tous, à remplir les prisons d'innocents et à concentrer le pouvoir. Bukele s'est d'ailleurs fait réélire malgré l'interdiction de la Constitution. La sécurité durable se construit avec une police d'enquête, une justice qui fonctionne et la lutte contre le trafic, pas en supprimant l'État de droit.",
 empathie="Quand on entend parler de règlements de comptes et de trafics, on peut envier un pays qui affiche presque plus de meurtres. Cette envie de sécurité est légitime ; il faut juste savoir ce qu'elle a coûté là-bas.",
 legitimes=["La baisse des homicides est réelle et massive.", "Une grande partie des Salvadoriens soutient cette politique.", "Les gangs salvadoriens terrorisaient réellement la population."],
 contre=[
  ("Les Salvadoriens sont contents, c'est eux que ça regarde.", "Les innocents arrêtés, les familles des 470 morts en détention et les enfants emprisonnés sont aussi des Salvadoriens ; une majorité ne rend pas légitime la suppression des droits d'une minorité."),
  ("Il faut la même fermeté contre les narcotrafiquants français.", "La fermeté n'exige pas d'arrêter sans preuve : en France, le problème est surtout le manque d'enquêteurs et de juges, pas l'excès de libertés."),
 ],
 questions=["Accepterais-tu d'être arrêté sans preuve, sur ton apparence, si ça faisait baisser la délinquance ?", "Que se passe-t-il quand un pouvoir qui a suspendu les libertés décide qui est un « criminel » ?"],
 limites=["Les chiffres d'homicides officiels sont jugés peu vérifiables par plusieurs sources.", "Le nombre de morts en détention varie selon les sources et les dates (de 354 à 470).", "La comparaison chiffrée avec la France repose sur des ordres de grandeur ; les sources lues ne la font pas directement."],
 publics={'convaincus': "Oui, les meurtres ont chuté au Salvador, c'est un fait. Mais le prix, c'est 90 000 arrestations, des milliers d'innocents en prison et au moins 470 morts en détention. Et avant, le gouvernement avait négocié avec les gangs. Tu voudrais d'un pays où la police peut t'arrêter pour un tatouage ?",
  'indecis': "La baisse des homicides au Salvador est spectaculaire, mais le pays partait d'une situation sans commune mesure avec la France. Elle a été obtenue en suspendant les libertés, avec de nombreux innocents emprisonnés. Une sécurité durable passe par des enquêteurs et une justice efficace."},
 a_actualiser='2027-07-31', raison="Fin éventuelle du régime d'exception, nouveaux rapports d'ONG et chiffres 2026.",
))

# 10 ── Faire payer les frais d'incarcération aux détenus ───────────────────
FI_AN_RAPPORT_2025 = ('fi_an_rapport_2025', src("Rapport n° 1585 sur la proposition de loi visant à instaurer une participation des détenus aux frais d'incarcération", 'Assemblée nationale, commission des lois', '16 juin 2025',
  'https://questions.assemblee-nationale.fr/dyn/17/rapports/cion_lois/l17b1585_rapport-fond.pdf',
  "Le texte crée une participation proportionnée aux ressources et au patrimoine, selon un barème fixé par décret. Coût d'une journée de détention : 130 € selon l'administration pénitentiaire (environ 3,7 milliards d'euros par an), 105 € selon la Cour des comptes, 127 € selon le Conseil de l'Europe (2023). De 1975 à 2003, l'article D. 112 du code de procédure pénale prévoyait un prélèvement pour frais d'entretien sur le produit du travail, limité à 30 % et réservé aux détenus qui travaillaient ; il a été supprimé par la loi du 9 septembre 2002 et un décret de 2003. Depuis 2022, l'article L. 412-20 du code pénitentiaire interdit ce prélèvement. Adoption en commission le 16 juin 2025.",
  "Rapport parlementaire officiel (texte porté par le groupe UDR, allié du RN).", 'primaire'))
FI_AN_DOC_2025 = ('fi_an_doc_2025', src("Document de travail du rapporteur, proposition de loi n° 1409 (participation des détenus aux frais d'incarcération)", 'Assemblée nationale', '16 juin 2025',
  "https://www.assemblee-nationale.fr/dyn/contenu/visualisation/924907/file/EAT%20-%20PPL%201409%20Participation%20des%20d%C3%A9tenus%20aux%20frais%20d%27incarc%C3%A9ration.pdf",
  "83 681 personnes détenues au 1er mai 2025, contre près de 37 000 en 1980. Budget de l'administration pénitentiaire : 2,7 milliards d'euros en 2010, 5,2 milliards en 2025. Coût d'une journée : 105 € selon la Cour des comptes, 127 € selon le Conseil de l'Europe, contre une moyenne européenne de 131,50 €.",
  "Document parlementaire.", 'primaire'))
FI_OIP_2025 = ('fi_oip_2025', src("Note aux membres de la commission des lois sur la proposition de loi « participation des personnes détenues aux frais d'incarcération »", 'Observatoire international des prisons, section française', '12 juin 2025',
  'https://oip.org/wp-content/uploads/2025/06/oip-sf-juin-2025-an-comloi-note-sur-la-ppl-visant-a-instaurer-une-participation-des-personnes-detenues-aux-frais-dincarceration.pdf',
  "Selon le ministère de la Justice, « une personne détenue sur cinq est indigente, c'est-à-dire a moins de 60 € par mois ». Plus de la moitié des détenus étaient sans emploi avant leur incarcération et 8 % sans domicile. Il faut 300 à 800 € par mois pour vivre décemment en détention (Emmaüs et Secours catholique, 2021). Moins d'un tiers des détenus travaille, pour 20 à 45 % du Smic. Le Contrôleur général des lieux de privation de liberté relève un espace par personne « le plus souvent très inférieure à 3m² ».",
  "Association de défense des droits des détenus (plaidoyer).", 'secondaire'))
FI_PUBLICSENAT_2025 = ('fi_publicsenat_2025', src("Faire payer aux détenus une partie de leurs frais d'incarcération, comme le veut Gérald Darmanin ? « Une idée à la noix », fustige Jérôme Durain", 'Public Sénat (Théodore Azouze)', '29 avril 2025',
  'https://www.publicsenat.fr/actualites/societe/faire-payer-aux-detenus-une-partie-de-leurs-frais-dincarceration-comme-le-veut-gerald-darmanin-une-idee-a-la-noix-fustige-jerome-durain-ps',
  "Le 28 avril 2025, le ministre de la Justice déclare : « Jusqu'à 2003, les détenus participaient aux frais d'incarcération » et « Je vais rétablir ces frais d'incarcération », évoquant un coût des prisons de « près de 4 milliards d'euros par an ». Le sénateur socialiste Jérôme Durain dénonce la « démagogie la plus caricaturale » : « On ne va pas aller faire les poches des détenus pour financer leur incarcération. » Il propose plutôt de développer amendes, saisies et confiscations.",
  "Chaîne parlementaire.", 'secondaire'))

FICHES.append(fiche(
 id='detenus-payer-incarceration', affirmation="Les détenus devraient payer eux-mêmes leurs frais de prison.", volet='securite', sous_theme='Prisons',
 mots_cles=['frais d incarceration', 'detenus payer prison', 'faire payer les prisonniers', 'prisonniers payent leur prison', 'cout d un detenu', 'darmanin frais d incarceration', 'prison payee par les contribuables', 'detenus nourris loges'],
 verdict='opinion', fiabilite='etabli',
 resume="C'est un choix politique, défendu notamment par le ministre de la Justice en 2025 et adopté en commission à l'Assemblée. Mais les faits limitent fortement son intérêt : une journée de détention coûte entre 105 et 130 €, alors qu'un détenu sur cinq vit avec moins de 60 € par mois et que moins d'un tiers travaille, payé 20 à 45 % du Smic. Un prélèvement a existé jusqu'en 2003, mais seulement sur les détenus qui travaillaient, plafonné à 30 %.",
 contexte="Avec des prisons surpeuplées et un budget pénitentiaire de plus de 5 milliards d'euros, l'idée de faire payer les détenus revient régulièrement, de la droite à l'extrême droite.",
 explication="Il faut comparer le coût d'une journée de prison avec les ressources réelles des détenus, rappeler ce qui existait avant 2003 et se demander qui paierait en pratique.",
 sources=[FI_AN_RAPPORT_2025, FI_AN_DOC_2025, FI_OIP_2025, FI_PUBLICSENAT_2025],
 faits=[
  fait("Une journée de détention coûte 105 € selon la Cour des comptes, 127 € selon le Conseil de l'Europe et 130 € selon l'administration pénitentiaire.", 'fi_an_rapport_2025', '2023-2025', 'France', "Aucun détenu ou presque ne pourrait payer une telle somme.", 'etabli', '105 à 130 €'),
  fait("Selon le ministère de la Justice, une personne détenue sur cinq est indigente, avec moins de 60 € par mois ; moins d'un tiers des détenus travaille, pour 20 à 45 % du Smic.", 'fi_oip_2025', '2025', 'France', "La plupart des détenus n'ont presque pas de ressources.", 'etabli', '1 sur 5'),
  fait("De 1975 à 2003, un prélèvement pour frais d'entretien existait, mais seulement sur le salaire des détenus qui travaillaient et plafonné à 30 % ; il a été supprimé en 2002-2003 et est interdit par le code pénitentiaire depuis 2022.", 'fi_an_rapport_2025', '1975-2022', 'France', "Le ministre a raison de dire qu'il existait, mais il ne concernait qu'une minorité.", 'etabli', '30 %'),
  fait("La population carcérale est passée de près de 37 000 personnes en 1980 à 83 681 au 1er mai 2025, et le budget de l'administration pénitentiaire de 2,7 milliards d'euros en 2010 à 5,2 milliards en 2025.", 'fi_an_doc_2025', '1980-2025', 'France', "Le coût augmente surtout parce qu'on enferme beaucoup plus.", 'etabli', '83 681'),
  fait("Fait défavorable : l'idée a des soutiens au-delà de l'extrême droite : le ministre de la Justice l'a reprise en 2025 et une proposition de loi a été adoptée en commission le 16 juin 2025.", 'fi_publicsenat_2025', '2025', 'France', "C'est un débat politique réel, pas une idée marginale.", 'etabli'),
 ],
 court="Une journée de prison coûte 105 à 130 €. Or un détenu sur cinq vit avec moins de 60 € par mois et moins d'un tiers travaille. Le prélèvement qui existait avant 2003 ne touchait que ceux qui travaillaient, plafonné à 30 %. Faire payer les détenus rapporterait peu et pénaliserait les familles et la réinsertion.",
 moyen="Une journée de détention coûte entre 105 et 130 € selon les sources. Mais un détenu sur cinq a moins de 60 € par mois, et moins d'un tiers travaille, payé 20 à 45 % du Smic. Il faut déjà 300 à 800 € par mois pour vivre décemment en prison : cantine, téléphone, produits d'hygiène.\n\nUn prélèvement existait de 1975 à 2003, mais seulement sur le salaire de ceux qui travaillaient, plafonné à 30 %. Le rétablir est un choix politique possible ; il rapporterait peu, et l'argent manquerait pour indemniser les victimes, aider les familles et préparer la sortie.",
 detaille="L'idée est simple : un détenu est logé et nourri par l'État, il devrait donc payer. Le ministre de la Justice l'a reprise en 2025, et une proposition de loi a été adoptée en commission à l'Assemblée. Elle prévoit une participation proportionnée aux ressources de chacun. Un prélèvement a d'ailleurs existé de 1975 à 2003 : il touchait le salaire des détenus qui travaillaient, dans la limite de 30 %.\n\nLe problème est l'écart entre le coût et les moyens. Une journée de détention coûte entre 105 et 130 € selon les sources. Or, selon le ministère de la Justice, un détenu sur cinq est indigent, avec moins de 60 € par mois ; plus de la moitié étaient sans emploi avant d'entrer en prison. Moins d'un tiers travaille, pour 20 à 45 % du Smic. Et la vie en prison coûte déjà cher aux détenus : il faut 300 à 800 € par mois pour acheter de quoi manger correctement, téléphoner à sa famille ou se laver. Prélever sur ces sommes, c'est surtout faire payer les familles, souvent modestes.\n\nLe vrai coût des prisons vient de l'enfermement massif : 83 681 détenus en 2025, plus du double de 1980. Réduire la surpopulation, développer les peines alternatives et préparer la sortie ferait baisser à la fois le coût et la récidive. Les sommes saisies sur les trafiquants et les condamnés solvables devraient d'abord aller aux victimes.",
 empathie="Il est compréhensible de trouver injuste que des personnes condamnées soient prises en charge par la collectivité. Ce sentiment de justice mérite qu'on regarde ce que la mesure rapporterait vraiment.",
 legitimes=["Un prélèvement existait bien avant 2003.", "Certains détenus, notamment des trafiquants, ont des ressources.", "Le coût des prisons augmente fortement."],
 contre=[
  ("Ils sont nourris et logés gratuitement.", "Ils paient déjà une grande partie de leur quotidien en prison (cantine, téléphone, hygiène), et un sur cinq a moins de 60 € par mois."),
  ("Les trafiquants ont de l'argent.", "Pour eux, la justice peut déjà saisir et confisquer les biens ; cet argent devrait aller en priorité aux victimes."),
 ],
 questions=["Sais-tu combien gagne un détenu qui travaille en prison ?", "Si on prélève sur un détenu sans ressources, qui paiera à sa place, à ton avis ?"],
 limites=["Le sort final de la proposition de loi en séance n'a pas pu être établi.", "Les données sur les ressources des détenus viennent d'une note de l'Observatoire international des prisons, qui cite le ministère.", "Les différents coûts journaliers ne reposent pas sur la même méthode."],
 publics={'convaincus': "Une journée de prison coûte 105 à 130 €, et un détenu sur cinq a moins de 60 € par mois. Le prélèvement d'avant 2003 ne touchait que ceux qui travaillaient, plafonné à 30 %. Au final, ce sont les familles qui paieraient ; pour les trafiquants, on peut déjà saisir leurs biens.",
  'indecis': "L'idée peut sembler juste, et elle a existé jusqu'en 2003. Mais la plupart des détenus n'ont presque rien, et beaucoup étaient sans emploi avant la prison. La mesure rapporterait peu ; réduire la surpopulation et la récidive ferait davantage baisser la facture."},
 a_actualiser='2027-06-30', raison="Suite législative de la proposition de loi et chiffres de la population carcérale.",
))

