FICHES.append(fiche(
 id='jo-paris-2024-cout', affirmation="Les Jeux olympiques de Paris ont coûté une fortune aux contribuables pour rien.", volet='economie', sous_theme='Services publics',
 mots_cles=['jo paris 2024 cout', 'cout des jeux olympiques', 'jeux olympiques contribuables', 'jo ont coute', 'cour des comptes jo', 'jo gaspillage', 'paris 2024 argent public', 'heritage des jo', 'seine baignable'],
 verdict='trompeur', fiabilite='etabli',
 resume="Trompeur. Le coût public est réel : environ 6,65 milliards d'euros selon la Cour des comptes, dont 3,63 milliards d'infrastructures. Mais le comité d'organisation s'est financé surtout par des recettes privées et a dégagé un bénéfice de 75,7 millions d'euros. L'héritage existe : 2 800 logements dans l'ancien village, une Seine en partie baignable, plus de 1 000 équipements sportifs. En revanche, l'effet sur l'économie a été faible : +0,07 point de PIB en 2024.",
 contexte="Avant et après les Jeux de Paris 2024, l'idée d'un gouffre financier payé par les contribuables a beaucoup circulé, en écho aux dérapages d'autres villes olympiques.",
 explication="Il faut distinguer le budget du comité d'organisation, largement privé, des dépenses publiques (sécurité, infrastructures), puis regarder les recettes, l'effet économique et ce qui reste après les Jeux.",
 sources=[JO_CDC_2025, JO_CDC_SYNTH_2025, JO_LOCALTIS_SEPT_2025, JO_BDF_2024, JO_PREFIDF_2025],
 faits=[
  fait("Selon la Cour des comptes, les dépenses publiques liées aux Jeux atteignent environ 6,65 milliards d'euros : 3,02 milliards pour l'organisation (dont la sécurité) et 3,63 milliards pour les infrastructures.", 'jo_cdc_2025', '2018-2025', 'France', "Le coût public est réel et important.", 'etabli', '6,65 Md€'),
  fait("Le comité d'organisation a perçu 4 494 millions d'euros de recettes, dont 224 millions de subventions publiques, et a dégagé un bénéfice de 75,7 millions : la garantie de l'État n'a pas joué.", 'jo_cdc_synth_2025', '2024-2025', 'France', "L'organisation elle-même a été financée surtout par le privé (billetterie, partenaires, CIO).", 'etabli', '75,7 M€'),
  fait("L'ancien village des athlètes devient 2 800 logements, avec 25 à 40 % de logements sociaux selon la commune, et plus de 1 000 équipements sportifs ont été financés en Île-de-France entre 2022 et 2024.", 'jo_prefidf_2025', '2022-2025', 'Île-de-France', "Une partie de la dépense reste utile aux habitants, surtout en Seine-Saint-Denis.", 'etabli', '2 800'),
  fait("Les sept premiers sites de baignade en Seine et Marne ont ouvert à l'été 2025, avec un objectif de 32 sites ; la dépollution de la Seine a mobilisé 1,1 milliard d'euros.", 'jo_cdc_synth_2025', '2025', 'Île-de-France', "Les Jeux ont accéléré des investissements écologiques attendus depuis des décennies.", 'etabli'),
  fait("Fait défavorable : la Cour estime l'effet des Jeux sur la croissance 2024 à seulement +0,07 point de PIB, juge l'impact économique « faible » et estime que les études préalables surestimaient les retombées.", 'jo_localtis_sept_2025', '2024-2025', 'France', "Les promesses de retombées économiques étaient exagérées.", 'etabli', '+0,07 point'),
  fait("Fait défavorable : seulement 245 places d'hébergement pérennes ont été créées pour les sans-abri, ce que la Cour juge limité.", 'jo_cdc_synth_2025', '2024-2025', 'Île-de-France', "L'héritage social est mince au regard des sommes engagées.", 'etabli', '245'),
 ],
 court="Le coût public des JO est réel : environ 6,65 milliards d'euros selon la Cour des comptes. Mais l'organisation, financée surtout par le privé, a dégagé un bénéfice, et il reste 2 800 logements, une Seine en partie baignable et 1 000 équipements sportifs. L'effet économique, lui, a été faible.",
 moyen="La Cour des comptes chiffre les dépenses publiques à environ 6,65 milliards d'euros, dont 3,63 milliards d'infrastructures et une grande part pour la sécurité. Le comité d'organisation, lui, s'est financé surtout avec la billetterie, les partenaires et le CIO, et a dégagé un bénéfice de 75,7 millions.\n\nCe n'est pas « pour rien » : l'ancien village devient 2 800 logements, des sites de baignade ont ouvert dans la Seine et la Marne, et plus de 1 000 équipements sportifs ont été financés. Mais la Cour juge l'effet économique faible (+0,07 point de PIB) et l'héritage social limité : seulement 245 places pérennes pour les sans-abri.",
 detaille="Il faut séparer deux budgets. Le comité d'organisation, chargé de faire tourner les Jeux, a perçu près de 4,5 milliards d'euros, venus surtout de la billetterie, des partenaires et du CIO ; les subventions publiques n'en représentaient qu'environ 5 %. Il a fini avec un bénéfice de 75,7 millions. Les dépenses publiques, elles, atteignent environ 6,65 milliards selon la Cour des comptes : 3,02 milliards pour l'organisation, dont la sécurité assurée en quasi-totalité par l'État, et 3,63 milliards pour les infrastructures.\n\nUne partie de cet argent laisse un héritage. Le village des athlètes, en Seine-Saint-Denis, devient 2 800 logements, dont une part de logements sociaux. La dépollution de la Seine a coûté 1,1 milliard d'euros, et des sites de baignade ont ouvert en 2025. Plus de 1 000 équipements sportifs ont été financés en Île-de-France. La Cour parle d'un héritage « riche et multiple ».\n\nMais il faut être lucide : l'effet économique a été faible, +0,07 point de PIB en 2024, loin des milliards promis par les études financées par les organisateurs. La croissance de l'été a été suivie d'un contrecoup. Et l'héritage social reste mince : 245 places pérennes pour les sans-abri, alors que des campements ont été évacués avant les Jeux. La question n'est pas de savoir si les JO ont coûté « pour rien », mais si les choix d'investissement ont assez profité aux habitants des quartiers populaires.",
 empathie="Quand on se serre la ceinture, voir des milliards dépensés pour un événement sportif peut révolter. C'est une vraie question de choix publics, qui mérite les chiffres de la Cour des comptes.",
 legitimes=["Le coût public est élevé, environ 6,65 milliards d'euros.", "L'effet économique a été faible.", "L'héritage social pour les plus pauvres est limité."],
 contre=[
  ("Les retombées économiques étaient bidon.", "C'est vrai que les promesses étaient exagérées ; mais les logements, les équipements sportifs et la Seine dépolluée sont des investissements qui restent."),
  ("Les contribuables ont tout payé.", "Le comité d'organisation a été financé à environ 95 % par des recettes privées et a fini en bénéfice ; ce sont surtout la sécurité et les infrastructures qui ont été publiques."),
 ],
 questions=["Savais-tu que le comité d'organisation des JO a fini en bénéfice ?", "Quels investissements laissés par les Jeux te semblent utiles, et lesquels auraient dû être prioritaires ?"],
 limites=["Les recettes fiscales et l'héritage sont encore provisoires selon la Cour.", "La qualité de l'eau de la Seine reste incertaine dans la durée.", "Le livret de la préfecture est une communication institutionnelle."],
 publics={'convaincus': "La Cour des comptes, qui n'est pas tendre, chiffre le coût public à 6,65 milliards et juge l'effet économique faible : sur ce point tu n'as pas tort. Mais l'organisation a été payée surtout par le privé et a fini en bénéfice, et il reste 2 800 logements et une Seine dépolluée. Ce n'est pas « pour rien ».",
  'indecis': "Les JO ont coûté cher à l'État, environ 6,65 milliards d'euros, et les retombées économiques ont été modestes. Mais une partie de l'argent a servi à des logements, des équipements sportifs et la dépollution de la Seine. La vraie question est de savoir si les habitants en profitent assez."},
 a_actualiser='2027-12-31', raison="Bilan définitif de l'héritage (logements, baignade) et des coûts.",
))

# 14 ── Expatriation des jeunes diplômés ────────────────────────────────────
EX_UFE_2026 = ('ex_ufe_2026', src("Rapport sur la situation des Français de l'étranger au 31 décembre 2025", "Union des Français de l'étranger (présentation du rapport du gouvernement)", '11 septembre 2026',
  'https://ufe.org/article-feed/rapport-situation-francais-de-letranger/',
  "« 1 784 975 inscrits » au registre des Français établis hors de France, en hausse de 1,7 % en 2025, retour au niveau d'avant le Covid. L'inscription n'étant pas obligatoire, « on estime néanmoins la population réelle des Français de l'étranger entre 2,8 et 3,2 millions ». Principaux pays : Suisse (168 881), États-Unis (168 529), Royaume-Uni (141 242), Belgique (126 452), Canada (119 054).",
  "Association des Français de l'étranger reprenant le rapport officiel.", 'secondaire'))
EX_TRESOR_2021 = ('ex_tresor_2021', src("De la France vers le monde : que révèle l'augmentation de l'émigration française ? (Trésor-Éco n° 275)", 'Direction générale du Trésor, avec l\'OCDE', '14 janvier 2021',
  'https://www.tresor.economie.gouv.fr/Articles/2021/01/14/de-la-france-vers-le-monde-que-revele-l-augmentation-de-l-emigration-francaise',
  "« près de 6 % des personnes nées en France et diplômées du supérieur résidaient en 2015-2016 » dans un autre pays de l'OCDE, contre 2 % pour les moins diplômés. Les taux d'émigration qualifiée sont « modestes, en particulier par rapport à certains pays européens comme l'Allemagne, le Royaume-Uni ou le Portugal ». Le taux global français de 2,7 % est « inférieur de deux points au taux observé pour l'Allemagne ». « Le choix de partir à l'étranger est motivé principalement par des raisons professionnelles », d'après une enquête présentée à titre indicatif.",
  "Administration économique ; données 2015-2016.", 'etude'))
EX_CAE_2025 = ('ex_cae_2025', src("Fiscalité du capital : quels sont les effets de l'exil fiscal sur l'économie ? (Focus n° 118)", "Conseil d'analyse économique (L. Bach, A. Bozio, N. Grimprel, A. Guillouzouic, C. Landais, C. Malgouyres)", 'juillet 2025',
  'https://cae-eco.fr/static/pdf/Focus_118_emigration_fiscale_250725_v2.pdf',
  "Environ 256 000 personnes ont quitté la France en 2017. Chaque année, « seulement 0,2% du top 1% français s'expatrie », contre 0,38 % pour l'ensemble de la population. Une hausse d'un point de l'imposition effective entraîne à long terme entre 0,02 % et 0,23 % d'expatriations supplémentaires parmi les hauts patrimoines. « les effets agrégés sur l'activité économique à long terme restent faibles ».",
  "Organisme de conseil économique rattaché au Premier ministre.", 'etude'))
EX_IPSOS_2025 = ('ex_ipsos_2025', src("Baromètre 2025 de la fuite des cerveaux", 'Ipsos bva pour la Fédération Syntec', '30 septembre 2025',
  'https://www.ipsos.com/fr-fr/barometre-2025-de-la-fuite-des-cerveaux',
  "Chaque année, « 10% des jeunes diplômés issus d'écoles d'ingénieurs » s'expatrient, contre 15 % des diplômés d'écoles de management. « 57% des talents interrogés envisagent une expatriation dans les trois prochaines années, dont 21% sérieusement. » Principaux inconvénients de la France cités : « La fiscalité trop élevée (charges sociales, impôts) » 48 %, « Le niveau des rémunérations trop faible » 36 %. Motivations de ceux qui envisagent de partir : découvrir une nouvelle culture (38 %), améliorer leurs conditions de vie (37 %), vivre une expérience professionnelle hors de France (34 %). 1 008 Bac+5 interrogés en ligne en juin 2025.",
  "Sondage commandé par une fédération patronale ; intentions déclarées.", 'etude'))
