FICHES.append(fiche(
 id='decroissance-retour-bougie', affirmation="Les écolos veulent la décroissance et nous faire revenir à la bougie.", volet='ecologie', sous_theme='Transition énergétique et emploi',
 mots_cles=['retour a la bougie', 'lampe a huile', 'decroissance', 'ecolos decroissance', 'modele amish', 'ecologistes veulent nous appauvrir', 'sobriete energetique', 'ecologie punitive', 'post croissance'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Trompeur. La « lampe à huile » est une caricature lancée par Emmanuel Macron en 2020. Les scénarios sérieux de transition (Ademe, RTE, négaWatt) reposent sur l'électricité, la rénovation et la technologie, avec plus ou moins de sobriété ; même le plus sobre de RTE prévoit une forte hausse de la consommation d'électricité. Le GIEC juge que la sobriété peut réduire de 40 à 70 % certaines émissions sans nuire au bien-être. Mais il est vrai que Les Écologistes revendiquent depuis 2025 une « décroissance démocratique de la production matérielle ».",
 contexte="Depuis la phrase d'Emmanuel Macron sur le « modèle Amish » et la « lampe à huile » en 2020, l'image d'écologistes voulant ramener la France au Moyen Âge est devenue un classique du débat.",
 explication="Il faut regarder d'où vient la formule, ce que disent les scénarios de transition et ce que proposent réellement les partis écologistes et de gauche.",
 sources=[DB_AFP_2020, DB_CITEPA_GIEC_2022, DB_ADEME_2021, DB_RTE_2022, DB_EELV_2025, DB_PUBLICSENAT_2022],
 faits=[
  fait("La formule du « retour à la lampe à huile » vient d'Emmanuel Macron, qui l'a employée en septembre 2020 pour moquer les élus demandant un moratoire sur la 5G.", 'db_afp_2020', '2020', 'France', "C'est une caricature politique, pas une proposition écologiste.", 'etabli'),
  fait("Selon le GIEC, les mesures sur la demande (sobriété) peuvent réduire de 40 à 70 % d'ici 2050 les émissions des secteurs concernés, tout en restant compatibles avec le bien-être de base pour tous.", 'db_citepa_giec_2022', '2022', 'Monde', "La sobriété n'est pas la misère : c'est consommer mieux, en particulier chez les plus riches.", 'etabli', '40 à 70 %'),
  fait("Dans les quatre scénarios de l'Ademe pour 2050, la consommation d'énergie baisse de 27 à 55 % par rapport à 2015 ; la décarbonation est « d'autant plus facilitée que la demande sera faible ».", 'db_ademe_2021', '2021', 'France', "Moins d'énergie ne veut pas dire revenir en arrière : les scénarios reposent sur la rénovation et l'efficacité.", 'etabli'),
  fait("Même dans sa variante « sobriété », le gestionnaire du réseau électrique prévoit environ 555 TWh d'électricité consommée en 2050, et cette variante coûterait environ 10 milliards d'euros par an de moins que la référence.", 'db_rte_2022', '2022', 'France', "La transition passe par l'électricité, l'inverse de la bougie.", 'estimation', '555 TWh'),
  fait("Fait défavorable : Les Écologistes ont adopté en octobre 2025 une motion pour une « décroissance démocratique de la production matérielle », avec l'arrêt ou la reconversion de secteurs comme l'aérien, la publicité ou le nucléaire.", 'db_eelv_2025', '2025', 'France', "Le mot « décroissance » est bien revendiqué par un parti, même s'il exclut « renoncement » et « récession ».", 'etabli'),
 ],
 court="La « lampe à huile » est une caricature lancée par Emmanuel Macron en 2020. Les scénarios de transition reposent sur l'électricité, la rénovation et les transports en commun. Les Écologistes parlent bien de « décroissance de la production matérielle », mais en défendant la santé, l'éducation et le soin.",
 moyen="La formule vient d'Emmanuel Macron, qui a moqué en 2020 le « modèle Amish » et le « retour à la lampe à huile ». Les scénarios sérieux de transition, ceux de l'Ademe ou du gestionnaire du réseau électrique, reposent sur l'électricité, la rénovation des logements et les transports collectifs. Même dans la variante la plus sobre, on consommerait beaucoup d'électricité en 2050.\n\nIl est vrai que Les Écologistes revendiquent depuis 2025 une « décroissance démocratique de la production matérielle » : moins d'aérien, de publicité, d'énergies fossiles, mais plus de santé, d'éducation et de réparation. Selon le GIEC, la sobriété peut fortement réduire les émissions sans nuire au bien-être de base.",
 detaille="L'image vient d'un président de la République : en septembre 2020, face à des élus de gauche et écologistes qui demandaient un moratoire sur la 5G, Emmanuel Macron a ironisé sur le « modèle Amish » et le « retour à la lampe à huile ». La caricature a fait florès. Elle ne correspond pas aux scénarios de transition étudiés en France. Ceux de l'Ademe prévoient pour 2050 une baisse de la consommation d'énergie de 27 à 55 %, grâce à la rénovation, aux transports en commun et à l'efficacité. Ceux du gestionnaire du réseau électrique prévoient au contraire une hausse de la consommation d'électricité, même dans la variante sobre, qui coûterait environ 10 milliards d'euros par an de moins.\n\nLe GIEC estime que la sobriété, c'est-à-dire réduire la demande par des villes compactes, le vélo, des logements rénovés et des produits réparables, peut réduire de 40 à 70 % les émissions des secteurs concernés d'ici 2050, tout en restant compatible avec le bien-être de base pour tous. Il souligne que les plus aisés émettent de façon disproportionnée : la sobriété concerne d'abord les jets privés et la surconsommation, pas le chauffage des ménages modestes.\n\nIl faut être honnête : le mot « décroissance » existe à gauche. Les Écologistes ont adopté en 2025 une motion pour une « décroissance démocratique de la production matérielle », avec l'arrêt ou la reconversion de l'aérien, de la publicité, du nucléaire et des énergies fossiles. Elle précise que ce n'est « ni renoncement ni récession » et veut renforcer la santé, l'éducation, l'agriculture vivrière et le soin. On peut débattre de ces choix ; mais il s'agit de produire autrement et de partager, pas de vivre à la bougie.",
 empathie="On peut craindre que l'écologie se traduise par des privations, surtout quand on a déjà du mal à boucler les fins de mois. C'est une inquiétude sérieuse, qui mérite qu'on regarde ce que proposent vraiment les scénarios.",
 legitimes=["Les Écologistes revendiquent une décroissance de la production matérielle.", "Les scénarios les plus sobres supposent de vrais changements de mode de vie, comme beaucoup moins de viande.", "Certaines mesures écologiques pèsent sur les ménages modestes."],
 contre=[
  ("Ils veulent interdire l'avion et la voiture.", "La motion des Écologistes vise à réduire l'aérien ; personne ne propose d'interdire la voiture, et les scénarios reposent sur des voitures électriques et plus de transports en commun."),
  ("La sobriété, c'est l'austérité pour les pauvres.", "Selon le GIEC, ce sont les plus aisés qui émettent le plus : la sobriété juste commence par eux, et par la rénovation des logements qui fait baisser les factures."),
 ],
 questions=["Savais-tu que la formule de la « lampe à huile » vient d'Emmanuel Macron ?", "Isoler son logement pour payer moins de chauffage, est-ce revenir à la bougie ?"],
 limites=["Le caractère minoritaire du courant décroissant à gauche n'a pas été chiffré dans les sources lues.", "Les scénarios de l'Ademe et de RTE ont été lus à travers des articles qui les résument.", "La phrase complète d'Emmanuel Macron n'a pas été lue."],
 publics={'convaincus': "La « lampe à huile », c'est une formule de Macron pour moquer ses opposants. Tous les scénarios sérieux prévoient plus d'électricité, des logements isolés et des transports en commun. Oui, des écologistes parlent de décroissance, mais pour réduire l'aérien et la publicité, pas pour couper le chauffage.",
  'indecis': "C'est légitime de craindre des privations. Mais les scénarios de transition reposent sur la rénovation et l'électricité, et le GIEC estime qu'on peut réduire fortement les émissions sans nuire au bien-être. Le vrai débat porte sur qui fait les efforts : les plus gros pollueurs d'abord."},
 a_actualiser='2027-06-30', raison="Programmes présidentiels 2027 et nouveaux scénarios de transition.",
))

